mapper.update:
UPDATE knowledge_document
SET status = 'EXPIRED', updated_at = #{now}
WHERE status = 'READY' AND expires_at IS NOT NULL AND expires_at <= #{now}

UPDATE integration_outbox
SET status = 'FAILED', next_attempt_at = #{now}
WHERE aggregate_type LIKE 'SEARCH\_%' ESCAPE '\\'
  AND status = 'PROCESSING' AND attempts < 8 AND next_attempt_at <= #{now}

mapper.insert:
INSERT IGNORE INTO admin_audit_log_archive
    (id, actor_user_id, target_user_id, action, before_value, after_value, created_at, archived_at)
SELECT id, actor_user_id, target_user_id, action, before_value, after_value, created_at, #{archivedAt}
FROM admin_audit_log WHERE created_at < #{cutoff}

mapper.delete:
DELETE source FROM admin_audit_log source
INNER JOIN admin_audit_log_archive archive ON archive.id = source.id
WHERE source.created_at < #{cutoff}
